<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Consent to Terms of Use</title>
  <style>
    :root {
      --color-bg: #f3f6fb;
      --color-surface: #ffffff;
      --color-text: #142033;
      --color-muted-text: #516079;
      --color-link: #2448d8;
      --color-border: #c8d3e5;
      --color-focus: #6f52ff;
      --color-danger: #b42318;
      --color-success: #0f7b45;
      --shadow-soft: 0 20px 45px -28px #13203a33;
      --radius-lg: 24px;
      --radius-md: 16px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top left, #ffffff 0, #f3f6fb 42%, #eaf0ff 100%);
      color: var(--color-text);
    }

    a {
      color: var(--color-link);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--color-surface);
      color: var(--color-text);
      transform: translateY(-220%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .panel {
      width: min(100%, 30rem);
      padding: 2rem;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-soft);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--color-link);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 4vw, 2.25rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.9rem 0 1.75rem;
      color: var(--color-muted-text);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      padding: 1rem;
      border: 1px solid var(--color-border);
      border-radius: var(--radius-md);
      background: #f9fbff;
    }

    .checkbox-row {
      display: flex;
      align-items: start;
      gap: 0.85rem;
    }

    input[type="checkbox"] {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0.15rem 0 0;
      accent-color: var(--color-link);
      flex: 0 0 auto;
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .required-marker {
      color: var(--color-danger);
      font-weight: 700;
    }

    .helper-text,
    .error-text,
    .status-text {
      margin: 0.75rem 0 0;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .error-text {
      color: var(--color-danger);
      font-weight: 600;
    }

    .status-text {
      min-height: 1.5rem;
      color: var(--color-success);
      font-weight: 600;
    }

    .button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      font: inherit;
      font-weight: 700;
      color: #ffffff;
      background: linear-gradient(135deg, #2448d8, #6f52ff);
      cursor: pointer;
    }

    .button:hover {
      filter: brightness(1.05);
    }

    .button:active {
      transform: translateY(1px);
    }

    a:focus-visible,
    input:focus-visible,
    .button:focus-visible {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 4px var(--color-focus);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    [hidden] {
      display: none;
    }

    @media (max-width: 30rem) {
      .panel {
        padding: 1.5rem;
      }

      .checkbox-row {
        gap: 0.75rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto;
        transition: none !important;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
      }

      .panel,
      .form-field {
        background: Canvas;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      a {
        color: LinkText;
      }

      .button {
        background: ButtonFace;
        color: ButtonText;
        border: 2px solid ButtonBorder;
      }

      a:focus-visible,
      input:focus-visible,
      .button:focus-visible {
        box-shadow: none;
        outline: 3px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <section class="panel" aria-labelledby="page-title">
      <p class="eyebrow">Quick confirmation</p>
      <h1 id="page-title">Agree to continue</h1>
      <p class="intro">Review the consent below, then submit to continue with your setup.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-error"
            >
            <label for="consent">
              I agree to the Terms of Use <span class="required-marker" aria-hidden="true">*</span>
              <span class="sr-only">required</span>
            </label>
          </div>
          <p id="consent-help" class="helper-text">Required to submit this form.</p>
          <p id="consent-error" class="error-text" hidden>Error: You must agree to the Terms of Use before continuing.</p>
        </div>

        <button class="button" type="submit">Continue</button>
        <p id="form-status" class="status-text" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('consent-form');
    const consentCheckbox = document.getElementById('consent');
    const consentError = document.getElementById('consent-error');
    const formStatus = document.getElementById('form-status');

    function showConsentError() {
      consentCheckbox.setAttribute('aria-invalid', 'true');
      consentError.hidden = false;
      formStatus.textContent = '';
      consentCheckbox.focus();
    }

    function clearConsentError() {
      consentCheckbox.removeAttribute('aria-invalid');
      consentError.hidden = true;
    }

    form.addEventListener('submit', function (event) {
      event.preventDefault();

      if (!consentCheckbox.checked) {
        showConsentError();
        return;
      }

      clearConsentError();
      formStatus.textContent = 'Consent received. You can continue.';
    });

    consentCheckbox.addEventListener('change', function () {
      if (consentCheckbox.checked) {
        clearConsentError();
        formStatus.textContent = '';
      }
    });
  </script>
</body>
</html>
