const { chromium } = require('playwright');
const axe = require('axe-core');
(async () => {
  let browser;
  try {
    browser = await chromium.launch();
  } catch (error) {
    if (String(error).includes("Executable doesn't exist")) {
      process.exit(2);
    }
    throw error;
  }
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => {
    const r = await window.axe.run();
    return {
      wcag: r.violations
        .filter((v) => !(v.tags || []).includes('best-practice'))
        .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bestPractice: r.violations
        .filter((v) => (v.tags || []).includes('best-practice'))
        .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  });
  await browser.close();
  console.log(JSON.stringify(result));
  process.exit(result.wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(String(error));
  process.exit(3);
});
